int validate_offset(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t min_size = h->min_size;
    size_t dir_length = sst->dir_length;
    const char *stream_start = (const char *)sst->data;
    const char *stream_end = stream_start + h->size;
    const char *check_end = (const char *)p + tail;

    if (check_end < stream_start || check_end > stream_end) {
        errno = EFTYPE;
        fprintf(stderr, "Invalid offset at line %d: stream [%p, %p], check [%p, %p]\n",
                line, stream_start, stream_end, stream_start, check_end);
        return -1;
    }

    if (dir_length > h->size) {
        errno = EFTYPE;
        fprintf(stderr, "Directory length exceeds stream size at line %d: dir_length=%zu, size=%zu\n",
                line, dir_length, h->size);
        return -1;
    }

    return 0;
}

int validate_stream_offset(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t min_size;
    const char *stream_start;
    const char *stream_end;

    min_size = sizeof(cdf_header_t);
    if (sst->dir_len < min_size) {
        errno = EFTYPE;
        return -1;
    }

    stream_start = (const char *)sst;
    stream_end = stream_start + sst->dir_len;

    if ((const char *)p < stream_start || (const char *)p + tail > stream_end) {
        errno = EFTYPE;
        return -1;
    }

    return 0;
}

int check_stream_offset_validity(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t stream_start = (size_t)sst;
    size_t stream_end = stream_start + h->min_size + sst->dir_length;
    size_t check_start = (size_t)p - tail;

    if (check_start < stream_start || check_start >= stream_end) {
        errno = EFTYPE;
        return -1;
    }
    return 0;
}

int check_offset_validity(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    const uint8_t *stream_start = (const uint8_t *)sst;
    const uint8_t *data_end = (const uint8_t *)p + tail;
    size_t header_min_size = h->min_size;
    size_t dir_length = sst->dir_length;

    if ((uint8_t *)data_end < stream_start || (uint8_t *)data_end > stream_start + header_min_size + dir_length) {
        fprintf(stderr, "Invalid offset at line %d: data_end=0x%p, stream_start=0x%p, stream_end=0x%p\n",
                line, (void *)data_end, (void *)stream_start, (void *)(stream_start + header_min_size + dir_length));
        errno = EFTYPE;
        return -1;
    }

    return 0;
}

int check_stream_offset(const cdf_stream_t *sst, const cdf_header_t *h, const void *p, size_t tail, int line) {
    size_t min_size = h->min_size;
    size_t dir_len = sst->dir_len;
    const char *stream_start = sst->data;
    const char *stream_end = stream_start + dir_len;
    const char *check_end = (const char *)p + tail;

    if (check_end < stream_start || check_end > stream_end) {
        errno = EFTYPE;
        return -1;
    }

    return 0;
}
